from typing import Any

class RuntimeOwnershipViolation(Exception):
    """Raised when an object is generated by an unauthorized platform."""
    pass

def validate_platform_ownership(obj: Any, expected_platform: str) -> None:
    """
    Validates that the provided object is strictly owned by the expected platform.
    
    Args:
        obj: The instantiated DTO or domain object.
        expected_platform: The platform string (e.g., 'Platform9') that must own this object.
        
    Raises:
        RuntimeOwnershipViolation: If the object's class is not allowed for the platform, 
                                   or if the instance explicitly declares a mismatched owner.
    """
    obj_type = type(obj).__name__
    
    # 1. Enforce Type-Level Platform Constraints
    if expected_platform == "Platform9":
        allowed_types = ["BaseFeature", "BooleanFeature", "FloatFeature"]
        forbidden_types = ["GeometryState", "TrendState", "MomentumState", "Indicator", "RawTick", "MarketEvent", "OHLC"]
        
        if obj_type in forbidden_types:
            raise RuntimeOwnershipViolation(f"Platform 9 cannot generate {obj_type}. Allowed types: {allowed_types}")
            
        # Optional strict mode: if obj_type not in allowed_types: raise ...
        
    elif expected_platform == "Platform10":
        if not obj_type.endswith("Concept") and obj_type != "Concept":
            raise RuntimeOwnershipViolation(f"Platform 10 can only generate Concepts. Received {obj_type}.")
            
    # 2. Enforce Instance-Level Ownership (If the object has an owner_platform attribute)
    if hasattr(obj, "owner_platform"):
        if obj.owner_platform != expected_platform:
            raise RuntimeOwnershipViolation(
                f"Ownership Violation: Object declares owner {obj.owner_platform}, but context expected {expected_platform}."
            )
